const checkAnswer = (given, correct) => given.trim().toLowerCase() === correct.trim().toLowerCase()
function scoreMessage(score, total) {
  const percent = score / total * 100
  let message = "Keep practising"
  if (percent >= 80) message = "Excellent!"
  else if (percent >= 50) message = "Good effort"
  return `You scored ${score}/${total}. ${message}`
}
function playQuiz(a1, a2, a3) {
  let score = 0
  if (checkAnswer(a1, "Abuja")) score++
  if (checkAnswer(a2, "12")) score++
  if (checkAnswer(a3, "Lagos")) score++
  return score
}
console.log(scoreMessage(playQuiz("Abuja", "13", " lagos "), 3))
